DO $$ BEGIN IF NOT EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='stores' AND c.relname='registers' AND c.relrowsecurity AND c.relforcerowsecurity) THEN RAISE EXCEPTION 'register RLS missing'; END IF; IF has_table_privilege('salekhpos_runtime','stores.registers','UPDATE') OR has_table_privilege('salekhpos_runtime','stores.registers','DELETE') THEN RAISE EXCEPTION 'unsafe register privileges'; END IF; END $$;
